Brief:
Slide coloured tiles on a small square board until each row holds a single colour. There is no timer, only moves.

Plan:
{"gameType":"puzzle-board","input":"tap-anywhere","lang":"en","loop":"Tap a tile to slide it into the empty slot on a small board, rearranging colours until every row is a single solid colour. The puzzle ends when you solve it or no moves remain.","slug":"colour-rows","style":"paper-cut","title":"Colour Rows"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Colour Rows</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
13|   }
14|   canvas {
15|     display: block;
16|     touch-action: none;
17|   }
18| </style>
19| </head>
20| <body>
21| <canvas id="game"></canvas>
22| <script>
23| // ---- Bridge helper (verbatim) ----
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| 
33| window.addEventListener("message", (event) => {
34|   const data = event.data;
35|   if (!data || data.source !== "cartridge-host") return;
36|   if (data.type === "pause") paused = true;
37|   if (data.type === "resume") paused = false;
38|   if (data.type === "reset") backToTitle();
39| });
40| 
41| // ---- Game setup ----
42| const canvas = document.getElementById("game");
43| const ctx = canvas.getContext("2d");
44| canvas.style.touchAction = "none";
45| 
46| let dpr = Math.max(1, window.devicePixelRatio || 1);
47| let W = 0, H = 0;
48| 
49| function resize() {
50|   W = window.innerWidth;
51|   H = window.innerHeight;
52|   dpr = Math.max(1, window.devicePixelRatio || 1);
53|   canvas.width = Math.floor(W * dpr);
54|   canvas.height = Math.floor(H * dpr);
55|   canvas.style.width = W + "px";
56|   canvas.style.height = H + "px";
57|   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
58|   draw();
59| }
60| window.addEventListener("resize", resize);
61| 
62| // ---- Paper-cut palette ----
63| const PAL = {
64|   bg: "#f4ecd8",
65|   layer: "#e07a5f",
66|   accent: "#3d405b",
67|   highlight: "#81b29a",
68| };
69| 
70| // A few extra colours for tiles (cut-paper feel), derived tastefully
71| const TILE_COLORS = ["#e07a5f", "#81b29a", "#3d405b", "#f2cc8f"];
72| 
73| // seeded jitter so it doesn't flicker between draws
74| function seededRand(seed) {
75|   let s = seed % 2147483647;
76|   if (s <= 0) s += 2147483646;
77|   return function () {
78|     s = (s * 16807) % 2147483647;
79|     return (s - 1) / 2147483646;
80|   };
81| }
82| const rand = seededRand(918273);
83| function jitter(px) {
84|   return (rand() - 0.5) * 2 * px;
85| }
86| 
87| // ---- Puzzle state ----
88| const ROWS = 3;
89| const COLS = 3;
90| const BOARD_SIZE = ROWS * COLS; // 9 cells, one empty
91| let board = []; // array of colour index, -1 = empty
92| let emptyIndex = 0;
93| let moves = 0;
94| let running = false;
95| let paused = false;
96| let gameOver = false;
97| let winFlag = false;
98| let stuckFlag = false;
99| let tapHintPulse = 0;
100| 
101| // Precompute jitter offsets per cell corner, stable per cell id
102| const cellJitters = {};
103| function getCellJitter(id) {
104|   if (!cellJitters[id]) {
105|     const localRand = seededRand(1000 + id * 37);
106|     cellJitters[id] = {
107|       tl: [(localRand() - 0.5) * 3, (localRand() - 0.5) * 3],
108|       tr: [(localRand() - 0.5) * 3, (localRand() - 0.5) * 3],
109|       br: [(localRand() - 0.5) * 3, (localRand() - 0.5) * 3],
110|       bl: [(localRand() - 0.5) * 3, (localRand() - 0.5) * 3],
111|     };
112|   }
113|   return cellJitters[id];
114| }
115| 
116| function makeSolvedBoard() {
117|   // Each row gets its own colour, filled fully, then remove one tile for empty slot
118|   const b = [];
119|   for (let r = 0; r < ROWS; r++) {
120|     for (let c = 0; c < COLS; c++) {
121|       b.push(r); // colour index = row index (0..ROWS-1), matches TILE_COLORS
122|     }
123|   }
124|   return b;
125| }
126| 
127| function isRowSolved(r, b) {
128|   const start = r * COLS;
129|   let colour = -2;
130|   for (let c = 0; c < COLS; c++) {
131|     const idx = start + c;
132|     if (b[idx] === -1) return false; // empty counts as not solved for that row unless we allow it
133|     if (colour === -2) colour = b[idx];
134|     else if (b[idx] !== colour) return false;
135|   }
136|   return true;
137| }
138| 
139| function solved() {
140|   for (let r = 0; r < ROWS; r++) {
141|     if (!isRowSolved(r, board)) return false;
142|   }
143|   return true;
144| }
145| 
146| function neighborsOf(idx) {
147|   const r = Math.floor(idx / COLS);
148|   const c = idx % COLS;
149|   const list = [];
150|   if (r > 0) list.push(idx - COLS);
151|   if (r < ROWS - 1) list.push(idx + COLS);
152|   if (c > 0) list.push(idx - 1);
153|   if (c < COLS - 1) list.push(idx + 1);
154|   return list;
155| }
156| 
157| function anyLegalMove() {
158|   // legal move = any neighbor of empty can slide (always true unless solved is the only state and there's no move to make progress)
159|   // Since a slide is always possible if empty has any neighbor, "stuck" happens only if no move can ever change the board's solved status.
160|   // For this puzzle, a legal move exists whenever empty has neighbors AND board is not already solved.
161|   if (solved()) return false;
162|   return neighborsOf(emptyIndex).length > 0;
163| }
164| 
165| function shuffleBoard() {
166|   // Start solved then perform random legal slides to scramble, guaranteeing solvability
167|   board = makeSolvedBoard();
168|   emptyIndex = Math.floor(BOARD_SIZE / 2);
169|   board[emptyIndex] = -1;
170|   // Actually need emptyIndex chosen consistently; recompute properly:
171|   board = makeSolvedBoard();
172|   const startEmpty = BOARD_SIZE - 1;
173|   board[startEmpty] = -1;
174|   emptyIndex = startEmpty;
175| 
176|   const scrambleSteps = 60 + Math.floor(rand() * 30);
177|   let lastMove = -1;
178|   for (let i = 0; i < scrambleSteps; i++) {
179|     const neigh = neighborsOf(emptyIndex).filter((n) => n !== lastMove);
180|     const pick = neigh.length > 0 ? neigh[Math.floor(rand() * neigh.length)] : neighborsOf(emptyIndex)[0];
181|     board[emptyIndex] = board[pick];
182|     board[pick] = -1;
183|     lastMove = emptyIndex;
184|     emptyIndex = pick;
185|   }
186|   // Avoid accidental already-solved shuffle
187|   if (solved()) {
188|     // do one more swap to break it, if possible
189|     const neigh = neighborsOf(emptyIndex);
190|     if (neigh.length > 0) {
191|       const pick = neigh[0];
192|       board[emptyIndex] = board[pick];
193|       board[pick] = -1;
194|       emptyIndex = pick;
195|     }
196|   }
197| }
198| 
199| function resetGameState() {
200|   moves = 0;
201|   gameOver = false;
202|   winFlag = false;
203|   stuckFlag = false;
204|   shuffleBoard();
205| }
206| 
207| function backToTitle() {
208|   running = false;
209|   paused = false;
210|   resetGameState();
211|   draw();
212| }
213| 
214| // ---- Drawing helpers (paper-cut style) ----
215| function roundRectPath(x, y, w, h, r) {
216|   ctx.beginPath();
217|   ctx.moveTo(x + r, y);
218|   ctx.arcTo(x + w, y, x + w, y + h, r);
219|   ctx.arcTo(x + w, y + h, x, y + h, r);
220|   ctx.arcTo(x, y + h, x, y, r);
221|   ctx.arcTo(x, y, x + w, y, r);
222|   ctx.closePath();
223| }
224| 
225| function drawJitteredRoundedRect(x, y, w, h, r, cellId) {
226|   const j = getCellJitter(cellId);
227|   ctx.beginPath();
228|   ctx.moveTo(x + r + j.tl[0], y + j.tl[1]);
229|   ctx.lineTo(x + w - r + j.tr[0], y + j.tr[1]);
230|   ctx.quadraticCurveTo(x + w + j.tr[0], y + j.tr[1], x + w + j.tr[0], y + r + j.tr[1]);
231|   ctx.lineTo(x + w + j.br[0], y + h - r + j.br[1]);
232|   ctx.quadraticCurveTo(x + w + j.br[0], y + h + j.br[1], x + w - r + j.br[0], y + h + j.br[1]);
233|   ctx.lineTo(x + r + j.bl[0], y + h + j.bl[1]);
234|   ctx.quadraticCurveTo(x + j.bl[0], y + h + j.bl[1], x + j.bl[0], y + h - r + j.bl[1]);
235|   ctx.lineTo(x + j.tl[0], y + r + j.tl[1]);
236|   ctx.quadraticCurveTo(x + j.tl[0], y + j.tl[1], x + r + j.tl[0], y + j.tl[1]);
237|   ctx.closePath();
238| }
239| 
240| function layout() {
241|   const margin = Math.min(W, H) * 0.08;
242|   const boardTop = H * 0.18;
243|   const boardSize = Math.min(W - margin * 2, H * 0.62);
244|   const cellSize = boardSize / COLS;
245|   const boardLeft = (W - boardSize) / 2;
246|   return { boardLeft, boardTop, boardSize, cellSize };
247| }
248| 
249| function drawBackground() {
250|   ctx.fillStyle = PAL.bg;
251|   ctx.fillRect(0, 0, W, H);
252| }
253| 
254| function drawTitlePlate() {
255|   const plateW = Math.min(W * 0.86, 520);
256|   const plateH = 90;
257|   const x = (W - plateW) / 2;
258|   const y = H * 0.05;
259| 
260|   ctx.save();
261|   ctx.shadowColor = "rgba(61,64,91,0.35)";
262|   ctx.shadowBlur = 6;
263|   ctx.shadowOffsetY = 4;
264|   ctx.fillStyle = PAL.accent;
265|   drawJitteredRoundedRect(x, y, plateW, plateH, 16, 9001);
266|   ctx.fill();
267|   ctx.restore();
268| 
269|   ctx.fillStyle = PAL.bg;
270|   ctx.font = "bold " + Math.floor(plateH * 0.4) + "px sans-serif";
271|   ctx.textAlign = "center";
272|   ctx.textBaseline = "middle";
273|   ctx.fillText("Colour Rows", W / 2, y + plateH / 2);
274| }
275| 
276| function drawBoard() {
277|   const { boardLeft, boardTop, boardSize, cellSize } = layout();
278| 
279|   // backing board plate (layer of card)
280|   ctx.save();
281|   ctx.shadowColor = "rgba(61,64,91,0.3)";
282|   ctx.shadowBlur = 6;
283|   ctx.shadowOffsetY = 4;
284|   ctx.fillStyle = PAL.accent;
285|   drawJitteredRoundedRect(boardLeft - 10, boardTop - 10, boardSize + 20, boardSize + 20, 20, 9002);
286|   ctx.fill();
287|   ctx.restore();
288| 
289|   for (let idx = 0; idx < BOARD_SIZE; idx++) {
290|     const r = Math.floor(idx / COLS);
291|     const c = idx % COLS;
292|     const x = boardLeft + c * cellSize;
293|     const y = boardTop + r * cellSize;
294|     const pad = cellSize * 0.06;
295|     const cx = x + pad;
296|     const cy = y + pad;
297|     const cw = cellSize - pad * 2;
298|     const ch = cellSize - pad * 2;
299| 
300|     const val = board[idx];
301|     if (val === -1) {
302|       // empty slot: draw a subtle inset
303|       ctx.save();
304|       ctx.fillStyle = "rgba(61,64,91,0.08)";
305|       drawJitteredRoundedRect(cx, cy, cw, ch, 10, idx + 500);
306|       ctx.fill();
307|       ctx.restore();
308|       continue;
309|     }
310| 
311|     ctx.save();
312|     ctx.shadowColor = "rgba(61,64,91,0.35)";
313|     ctx.shadowBlur = 6;
314|     ctx.shadowOffsetY = 3;
315|     ctx.fillStyle = TILE_COLORS[val % TILE_COLORS.length];
316|     drawJitteredRoundedRect(cx, cy, cw, ch, 10, idx);
317|     ctx.fill();
318|     ctx.restore();
319| 
320|     // highlight strip for depth
321|     ctx.save();
322|     ctx.globalAlpha = 0.18;
323|     ctx.fillStyle = PAL.bg;
324|     drawJitteredRoundedRect(cx + cw * 0.08, cy + ch * 0.08, cw * 0.5, ch * 0.25, 6, idx + 700);
325|     ctx.fill();
326|     ctx.restore();
327|   }
328| 
329|   // row solved indicators
330|   for (let r = 0; r < ROWS; r++) {
331|     if (isRowSolved(r, board)) {
332|       const y = boardTop + r * cellSize;
333|       ctx.save();
334|       ctx.strokeStyle = PAL.highlight;
335|       ctx.lineWidth = 3;
336|       ctx.beginPath();
337|       ctx.moveTo(boardLeft - 6, y + cellSize / 2);
338|       ctx.lineTo(boardLeft - 18, y + cellSize / 2);
339|       ctx.stroke();
340|       ctx.restore();
341|     }
342|   }
343| }
344| 
345| function drawHud() {
346|   ctx.fillStyle = PAL.accent;
347|   ctx.font = "bold 20px sans-serif";
348|   ctx.textAlign = "left";
349|   ctx.textBaseline = "top";
350|   ctx.fillText("Moves: " + moves, 16, H - 40);
351| }
352| 
353| function drawEndOverlay() {
354|   ctx.save();
355|   ctx.fillStyle = "rgba(61,64,91,0.55)";
356|   ctx.fillRect(0, 0, W, H);
357| 
358|   const plateW = Math.min(W * 0.8, 460);
359|   const plateH = 160;
360|   const x = (W - plateW) / 2;
361|   const y = (H - plateH) / 2;
362| 
363|   ctx.shadowColor = "rgba(0,0,0,0.3)";
364|   ctx.shadowBlur = 6;
365|   ctx.shadowOffsetY = 4;
366|   ctx.fillStyle = PAL.bg;
367|   drawJitteredRoundedRect(x, y, plateW, plateH, 18, 9003);
368|   ctx.fill();
369|   ctx.shadowBlur = 0;
370|   ctx.shadowOffsetY = 0;
371| 
372|   ctx.fillStyle = PAL.accent;
373|   ctx.textAlign = "center";
374|   ctx.textBaseline = "middle";
375|   ctx.font = "bold 28px sans-serif";
376|   const msg = winFlag ? "Solved!" : "No moves left";
377|   ctx.fillText(msg, W / 2, y + plateH * 0.4);
378| 
379|   ctx.font = "18px sans-serif";
380|   ctx.fillText("Moves: " + moves + " — tap to play again", W / 2, y + plateH * 0.72);
381|   ctx.restore();
382| }
383| 
384| function drawTitleScreen() {
385|   drawTitlePlate();
386| 
387|   // hint pulse
388|   tapHintPulse += 0.05;
389|   const alpha = 0.5 + 0.5 * Math.sin(tapHintPulse);
390|   ctx.save();
391|   ctx.globalAlpha = alpha;
392|   ctx.fillStyle = PAL.accent;
393|   ctx.font = "bold 22px sans-serif";
394|   ctx.textAlign = "center";
395|   ctx.textBaseline = "middle";
396|   ctx.fillText("Tap to begin", W / 2, H * 0.85);
397|   ctx.restore();
398| 
399|   // small preview board (static, decorative)
400|   drawBoard();
401| }
402| 
403| function draw() {
404|   drawBackground();
405| 
406|   if (!running) {
407|     drawTitleScreen();
408|     return;
409|   }
410| 
411|   drawTitlePlate();
412|   drawBoard();
413|   drawHud();
414| 
415|   if (gameOver) {
416|     drawEndOverlay();
417|   } else if (paused) {
418|     ctx.save();
419|     ctx.fillStyle = "rgba(61,64,91,0.5)";
420|     ctx.fillRect(0, 0, W, H);
421|     ctx.fillStyle = PAL.bg;
422|     ctx.font = "bold 26px sans-serif";
423|     ctx.textAlign = "center";
424|     ctx.textBaseline = "middle";
425|     ctx.fillText("Paused", W / 2, H / 2);
426|     ctx.restore();
427|   }
428| }
429| 
430| // ---- Interaction ----
431| function cellFromPoint(px, py) {
432|   const { boardLeft, boardTop, boardSize, cellSize } = layout();
433|   if (px < boardLeft || px > boardLeft + boardSize) return -1;
434|   if (py < boardTop || py > boardTop + boardSize) return -1;
435|   const c = Math.floor((px - boardLeft) / cellSize);
436|   const r = Math.floor((py - boardTop) / cellSize);
437|   if (c < 0 || c >= COLS || r < 0 || r >= ROWS) return -1;
438|   return r * COLS + c;
439| }
440| 
441| function isLegal(cell) {
442|   if (cell < 0 || cell >= BOARD_SIZE) return false;
443|   if (board[cell] === -1) return false;
444|   return neighborsOf(emptyIndex).includes(cell);
445| }
446| 
447| function apply(cell) {
448|   board[emptyIndex] = board[cell];
449|   board[cell] = -1;
450|   emptyIndex = cell;
451| }
452| 
453| function points() {
454|   // simple scoring: count solved rows
455|   let s = 0;
456|   for (let r = 0; r < ROWS; r++) if (isRowSolved(r, board)) s++;
457|   return s;
458| }
459| 
460| function onCellTapped(cell) {
461|   if (!isLegal(cell)) return;
462|   apply(cell);
463|   moves += 1;
464|   CARTRIDGE.send("score", { value: points() });
465|   if (solved()) {
466|     winFlag = true;
467|     gameOver = true;
468|     CARTRIDGE.send("end", { reason: "win", value: moves });
469|   } else if (!anyLegalMove()) {
470|     stuckFlag = true;
471|     gameOver = true;
472|     CARTRIDGE.send("end", { reason: "stuck" });
473|   }
474|   draw();
475| }
476| 
477| canvas.addEventListener("pointerdown", (event) => {
478|   event.preventDefault();
479|   if (paused) return;
480| 
481|   if (!running) {
482|     running = true;
483|     resetGameState();
484|     CARTRIDGE.send("start");
485|     draw();
486|     return;
487|   }
488| 
489|   const rect = canvas.getBoundingClientRect();
490|   const px = event.clientX - rect.left;
491|   const py = event.clientY - rect.top;
492| 
493|   if (gameOver) {
494|     resetGameState();
495|     draw();
496|     return;
497|   }
498| 
499|   const cell = cellFromPoint(px, py);
500|   if (cell >= 0) onCellTapped(cell);
501| });
502| 
503| // ---- Boot ----
504| resetGameState();
505| resize();
506| CARTRIDGE.send("boot", { title: "Colour Rows", gameType: "puzzle-board", lang: "en" });
507| draw();
508| 
509| // light animation loop just for the title pulse (no timers with strings, RAF used)
510| function loop() {
511|   if (!running && !paused) {
512|     draw();
513|   }
514|   requestAnimationFrame(loop);
515| }
516| requestAnimationFrame(loop);
517| </script>
518| </body>
519| </html>
520|

